<script lang="ts">
 let {title,files=[],onfiles,disabled=false,existing=0}:{title:string;files:File[];onfiles:(files:File[])=>void;disabled?:boolean;existing?:number}=$props();
 let error=$state('');
 function add(items:File[]){error='';if(disabled)return;if(items.some(f=>f.size>10*1024*1024)){error='Each file must be 10 MB or smaller.';return}if(files.length+existing+items.length>10){error='Maximum 10 files per section.';return}onfiles([...files,...items])}
</script>
<section class="upload"><h3>{title} <small>{existing+files.length}/10 files</small></h3><label class="drop" ondragover={e=>e.preventDefault()} ondrop={e=>{e.preventDefault();add(Array.from(e.dataTransfer?.files||[]))}}><span>Drop files here or choose files</span><input type="file" multiple {disabled} onchange={e=>{add(Array.from(e.currentTarget.files||[]));e.currentTarget.value=''}}/><small>Up to 10 files · 10 MB each</small></label>{#if error}<p role="alert">{error}</p>{/if}<ul>{#each files as file,i}<li><span>{file.name}</span><button type="button" {disabled} onclick={()=>onfiles(files.filter((_,n)=>n!==i))} aria-label={'Remove '+file.name}>Remove</button></li>{/each}</ul></section>
<style>.upload{min-width:0}h3{display:flex;align-items:center;justify-content:space-between;font-size:15px;margin:0 0 10px}small{font-size:12px;font-weight:400;color:#374151}.drop{display:grid;gap:8px;padding:16px;border:1px dashed #587d8c;border-radius:8px;background:#f2f8f8;color:#111}.drop:focus-within{outline:3px solid #087f83}input{max-width:100%;font:inherit}ul{list-style:none;padding:0;margin:8px 0}li{display:flex;gap:12px;align-items:center;justify-content:space-between;padding:6px 0}li span{overflow-wrap:anywhere;min-width:0}button{min-height:40px;background:white;border:1px solid #acbec8;border-radius:6px;color:#162d40;cursor:pointer}p{color:#a12624}</style>
